+          .isEqualTo(fstatus.getAccessTime());
+      assertThat(newStatus.getModificationTime())
+          .isEqualTo(dateObj.getTime());
+    }
+
+    {
+      // -c on an existing directory must still update the timestamps.
+      String strTime = formatTimestamp(System.currentTimeMillis() + 180000L);
+      Date dateObj = parseTimestamp(strTime);
+
+      assertThat(shellRun("-touch", "-c", "-t", strTime, newDirName))
+          .as("Expected successful touch on an existing directory" +
+              " with -c option")
+          .isEqualTo(0);
+      FileStatus newStatus = lfs.getFileStatus(newDir);
+      assertThat(newStatus.getAccessTime()).isEqualTo(dateObj.getTime());
+      assertThat(newStatus.getModificationTime()).isEqualTo(dateObj.getTime());
+    }
+
+    lfs.delete(newDir, true);
+  }
