36	/**
37	 * Unix touch like commands
38	 */
39	@InterfaceAudience.Private
40	@InterfaceStability.Unstable
41	
42	public class TouchCommands extends FsCommand {
43	  public static void registerCommands(CommandFactory factory) {
44	    factory.addClass(Touchz.class, "-touchz");
45	    factory.addClass(Touch.class, "-touch");
46	  }
47	
48	  /**
49	   * (Re)create zero-length file at the specified path.
50	   * This will be replaced by a more UNIX-like touch when files may be
51	   * modified.
52	   */
53	  public static class Touchz extends TouchCommands {
54	    public static final String NAME = "touchz";
55	    public static final String USAGE = "<path> ...";
56	    public static final String DESCRIPTION =
57	      "Creates a file of zero length " +
58	      "at <path> with current time as the timestamp of that <path>. " +
59	      "An error is returned if the file exists with non-zero length\n";
60	
61	    @Override
62	    protected void processOptions(LinkedList<String> args) {
63	      CommandFormat cf = new CommandFormat(1, Integer.MAX_VALUE);
64	      cf.parse(args);
65	    }
66	
67	    @Override
68	    protected void processPath(PathData item) throws IOException {
69	      if (item.stat.isDirectory()) {
70	        // TODO: handle this
71	        throw new PathIsDirectoryException(item.toString());
72	      }
73	      if (item.stat.getLen() != 0) {
74	        throw new PathIOException(item.toString(), "Not a zero-length file");
75	      }
76	      touchz(item);
77	    }
78	
79	    @Override
80	    protected void processNonexistentPath(PathData item) throws IOException {
81	      if (!item.parentExists()) {
82	        throw new PathNotFoundException(item.toString())
83	            .withFullyQualifiedPath(item.path.toUri().toString());
84	      }
85	      touchz(item);
86	    }
87	
88	    private void touchz(PathData item) throws IOException {
89	      item.fs.create(item.path).close();
90	    }
91	  }
92	
93	  /**
94	   * A UNIX like touch command.
95	   */
96	  public static class Touch extends TouchCommands {
97	    private static final String OPTION_CHANGE_ONLY_MODIFICATION_TIME = "m";
98	    private static final String OPTION_CHANGE_ONLY_ACCESS_TIME = "a";
99	    private static final String OPTION_USE_TIMESTAMP = "t";
100	    private static final String OPTION_DO_NOT_CREATE_FILE = "c";
101	
102	    public static final String NAME = "touch";
103	    public static final String USAGE = "[-" + OPTION_CHANGE_ONLY_ACCESS_TIME
104	        + "] [-" + OPTION_CHANGE_ONLY_MODIFICATION_TIME + "] [-"
105	        + OPTION_USE_TIMESTAMP + " TIMESTAMP (yyyyMMdd:HHmmss) ] "
106	        + "[-" + OPTION_DO_NOT_CREATE_FILE + "] <path> ...";
107	    public static final String DESCRIPTION =
108	        "Updates the access and modification times of the file specified by the"
109	            + " <path> to the current time. If the file does not exist, then a zero"
110	            + " length file is created at <path> with current time as the timestamp"
111	            + " of that <path>.\n"
112	            + "-" + OPTION_CHANGE_ONLY_ACCESS_TIME
113	            + " Change only the access time \n" + "-"
114	            + OPTION_CHANGE_ONLY_MODIFICATION_TIME
115	            + " Change only the modification time \n" + "-"
116	            + OPTION_USE_TIMESTAMP + " TIMESTAMP"
117	            + " Use specified timestamp instead of current time\n"
118	            + " TIMESTAMP format yyyyMMdd:HHmmss\n"
119	            + "-" + OPTION_DO_NOT_CREATE_FILE + " Do not create any files";
120	
121	    private boolean changeModTime = false;
122	    private boolean changeAccessTime = false;
123	    private boolean doNotCreate = false;
124	    private String timestamp;
125	    private final SimpleDateFormat dateFormat =
126	        new SimpleDateFormat("yyyyMMdd:HHmmss");
127	
128	    @InterfaceAudience.Private
129	    @VisibleForTesting
130	    public DateFormat getDateFormat() {
131	      return dateFormat;
132	    }
133	
134	    @Override
135	    protected void processOptions(LinkedList<String> args) {
136	      this.timestamp =
137	          StringUtils.popOptionWithArgument("-" + OPTION_USE_TIMESTAMP, args);
138	
139	      CommandFormat cf = new CommandFormat(1, Integer.MAX_VALUE,
140	          OPTION_USE_TIMESTAMP, OPTION_CHANGE_ONLY_ACCESS_TIME,
141	          OPTION_CHANGE_ONLY_MODIFICATION_TIME, OPTION_DO_NOT_CREATE_FILE);
142	      cf.parse(args);
143	      this.changeModTime = cf.getOpt(OPTION_CHANGE_ONLY_MODIFICATION_TIME);
144	      this.changeAccessTime = cf.getOpt(OPTION_CHANGE_ONLY_ACCESS_TIME);
145	      this.doNotCreate = cf.getOpt(OPTION_DO_NOT_CREATE_FILE);
146	    }
147	
148	    @Override
149	    protected void processPath(PathData item) throws IOException {
150	      touch(item);
151	    }
152	
153	    @Override
154	    protected void processNonexistentPath(PathData item) throws IOException {
155	      if (!item.parentExists()) {
156	        throw new PathNotFoundException(item.toString())
157	            .withFullyQualifiedPath(item.path.toUri().toString());
158	      }
159	      touch(item);
160	    }
161	
162	    private void touch(PathData item) throws IOException {
163	      if (!item.fs.exists(item.path)) {
164	        if (doNotCreate) {
165	          return;
166	        }
167	        item.fs.create(item.path).close();
168	        if (timestamp != null) {
169	          // update the time only if user specified a timestamp using -t option.
170	          updateTime(item);
171	        }
172	      } else {
173	        updateTime(item);
174	      }
175	    }
176	
177	    private void updateTime(PathData item) throws IOException {
178	      long time = System.currentTimeMillis();
179	      if (timestamp != null) {
180	        try {
181	          time = dateFormat.parse(timestamp).getTime();
182	        } catch (ParseException e) {
183	          throw new IllegalArgumentException(
184	              "Unable to parse the specified timestamp "+ timestamp
185	              + ". The expected format is " + dateFormat.toPattern(), e);
186	        }
187	      }
188	      if (changeModTime ^ changeAccessTime) {
189	        long atime = changeModTime ? -1 : time;
190	        long mtime = changeAccessTime ? -1 : time;
191	        item.fs.setTimes(item.path, mtime, atime);
192	      } else {
193	        item.fs.setTimes(item.path, time, time);
194	      }
195	    }
196	  }
197	}
